/* Current-year observations stay separate from complete-year model training. */
(() => {
  const $=id=>document.getElementById(id),cache=new Map();let token=0,latest;
  async function json(url){const r=await fetch(url);if(!r.ok)throw Error('The 2026 records are still being prepared.');return r.json();}
  async function binary(path){const key='./observed2026/'+path;if(!cache.has(key))cache.set(key,fetch(key).then(async r=>{if(!r.ok)throw Error('Current-year record unavailable.');const raw=await r.arrayBuffer();return path.endsWith('.gz')?new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer():raw;}).catch(error=>{cache.delete(key);throw error;}));return cache.get(key);}
  async function load(product,native){const manifest=await json('./observed2026/manifest.json'),info=manifest.products[product];if(!info)throw Error('This product is still being prepared.');const index=await json('./observed2026/'+info.index),count=index.dates.length,chunk=Math.floor(native/index.chunkSize),row=native%index.chunkSize,folder=product+'/'+String(chunk).padStart(4,'0')+'/',suffix=index.binarySuffix||'.bin.gz',fields=['sst','anomaly','intensity','mhw'],raw=await Promise.all(fields.map(name=>binary(folder+name+suffix))),values={};fields.forEach((name,k)=>{const array=name==='mhw'?new Uint8Array(raw[k]):new Int16Array(raw[k]);values[name]=Array.from(array.slice(row*count,(row+1)*count),v=>name==='mhw'?v:v===-32768?null:v/100);if(values[name].length!==count)throw Error('Current-year record dimensions differ.');});return {manifest,index,values};}
  async function render(){if(document.documentElement.dataset.ready!=='true'||!$('pointAnalysis')?.open)return;const d=AtlasUI.snapshot(),ticket=++token;let product=d.state.product,native=d.point[product==='mur'?4:5];try{let data;try{data=await load(product,native);}catch(error){if(product!=='mur')throw error;product='oisst';native=d.point[5];data=await load(product,native);}if(ticket!==token)return;latest=data;const {index,values}=data,threshold=values.sst.map((v,i)=>v===null?null:v-values.intensity[i]),mhw=values.sst.map((v,i)=>values.mhw[i]?v:null),days=values.mhw.reduce((a,b)=>a+b,0);$('observed2026Plot').hidden=false;$('observed2026Csv').hidden=false;$('observed2026Note').textContent=`${product==='mur'?'GHRSST MUR':'NOAA OISST'} · 1 Jan–${new Date(index.dateEnd+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})} · ${days} observed heatwave days at this SST source cell.`;
      await Plotly.react('observed2026Plot',[{x:index.dates,y:values.sst,name:'Daily SST',mode:'lines',line:{color:'#355c7d',width:1.2}},{x:index.dates,y:threshold,name:'90th-percentile threshold',mode:'lines',line:{color:'#777',width:1.2,dash:'dot'}},{x:index.dates,y:mhw,name:'Heatwave days',mode:'markers',marker:{color:'#98614d',size:3}}],{paper_bgcolor:'transparent',plot_bgcolor:'transparent',margin:{l:60,r:24,t:35,b:42},legend:{orientation:'h',y:1.15},font:{size:11},hovermode:'x unified',xaxis:{type:'date',tickformat:'%b'},yaxis:{title:'SST (°C)'},shapes:[{type:'rect',xref:'x',yref:'paper',x0:index.dates[Math.max(0,index.dates.length-(index.trailingEventCheckDays||6))],x1:index.dateEnd,y0:0,y1:1,fillcolor:'#8996a21a',line:{width:0}}]},{responsive:true,displaylogo:false,toImageButtonOptions:{format:'svg',filename:'observed_2026'}});
      await comparison(product,native,ticket);
      $('observed2026Source').textContent=`${index.source}. SST source: ${d.meta.products[product].cells[native][1]}°N, ${d.meta.products[product].cells[native][0]}°E. Fixed ${product==='mur'?'2003–2022':'1982–2011'} baseline. 2026 is incomplete; event membership near the end of the record can change as new observations arrive.`;
    }catch(error){if(ticket!==token)return;latest=null;$('observed2026Plot').hidden=true;$('observed2026Csv').hidden=true;$('observed2026Note').textContent=error.message;$('observed2026Source').textContent='Follow the download and analysis on the progress page.';}}
  async function comparison(product,native,ticket){try{const metadata=await json('./observed2026/analysis.json'),info=metadata.products[product];if(!info)return;const chunk=Math.floor(native/info.chunkSize),row=native%info.chunkSize,raw=await binary(info.files[chunk]),a=new Uint16Array(raw),y=Array.from(a.slice(row*info.years.length,(row+1)*info.years.length));if(ticket!==token)return;$('observed2026Comparison').hidden=false;const month=new Intl.DateTimeFormat('en',{month:'short'}).format(new Date(2026,info.endMonth-1,15));await Plotly.react('observed2026Comparison',[{x:info.years,y,name:'Observed MHW days · Jan–'+month,mode:'lines+markers',line:{color:'#355c7d',width:1.5},marker:{size:info.years.map((_,i)=>i===info.years.length-1?7:3),color:info.years.map((_,i)=>i===info.years.length-1?'#98614d':'#355c7d')}}],{paper_bgcolor:'transparent',plot_bgcolor:'transparent',margin:{l:60,r:24,t:30,b:42},font:{size:11},xaxis:{tickformat:'d'},yaxis:{title:'MHW days · Jan–'+month}},{responsive:true,displaylogo:false,toImageButtonOptions:{format:'svg',filename:'matched_months_heatwaves'}});$('observed2026ComparisonCaption').textContent=`January–${month} heatwave days in each year. Every year uses the same completed months, including 2026.`;}catch{}}
  $('observed2026Csv').onclick=()=>{if(!latest)return;const {index,values}=latest,lines=['date,sst_degC,threshold_degC,anomaly_degC,mhw_member'];index.dates.forEach((date,i)=>lines.push([date,values.sst[i],values.sst[i]-values.intensity[i],values.anomaly[i],values.mhw[i]].join(',')));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));a.download='habitat_observations_2026.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
  for(const event of ['atlaspixelchange','atlaspointwindowopen'])window.addEventListener(event,render);
  async function forPoint(pixel,product){const d=AtlasUI.snapshot();try{let native=d.pixels[pixel][product==='mur'?4:5],data;try{data=await load(product,native);}catch(error){if(product!=='mur')throw error;product='oisst';native=d.pixels[pixel][5];data=await load(product,native);}return {...data,product,source:d.meta.products[product].cells[native]};}catch{return null;}}
  window.AtlasObserved2026={load,render,forPoint};
})();
